CREATE TYPE "service_account_status" AS ENUM ('ACTIVE','DISABLED','ARCHIVED');CREATE TYPE "api_key_status" AS ENUM ('ACTIVE','REVOKED');CREATE TYPE "api_key_environment" AS ENUM ('LIVE','TEST','DEVELOPMENT');
CREATE TABLE "service_accounts"("id" UUID NOT NULL DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"name" VARCHAR(120) NOT NULL,"description" VARCHAR(500),"status" "service_account_status" NOT NULL DEFAULT 'ACTIVE',"created_by_user_id" UUID NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"deleted_at" TIMESTAMP(3),CONSTRAINT "service_accounts_pkey" PRIMARY KEY("id"));
CREATE TABLE "api_keys"("id" UUID NOT NULL DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"service_account_id" UUID NOT NULL,"name" VARCHAR(120) NOT NULL,"key_prefix" VARCHAR(16) NOT NULL,"public_id" VARCHAR(32) NOT NULL,"masked_value" VARCHAR(80) NOT NULL,"secret_hash" CHAR(64) NOT NULL,"hash_version" INTEGER NOT NULL DEFAULT 1,"environment" "api_key_environment" NOT NULL,"status" "api_key_status" NOT NULL DEFAULT 'ACTIVE',"expires_at" TIMESTAMP(3),"last_used_at" TIMESTAMP(3),"revoked_at" TIMESTAMP(3),"created_by_user_id" UUID NOT NULL,"revoked_by_user_id" UUID,"replacement_key_id" UUID,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "api_keys_pkey" PRIMARY KEY("id"));
CREATE TABLE "service_account_roles"("service_account_id" UUID NOT NULL,"role_id" UUID NOT NULL,"assigned_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "service_account_roles_pkey" PRIMARY KEY("service_account_id","role_id"));
CREATE UNIQUE INDEX "service_accounts_organization_id_name_key" ON "service_accounts"("organization_id","name");CREATE INDEX "service_accounts_organization_id_idx" ON "service_accounts"("organization_id");CREATE UNIQUE INDEX "api_keys_public_id_key" ON "api_keys"("public_id");CREATE UNIQUE INDEX "api_keys_replacement_key_id_key" ON "api_keys"("replacement_key_id");CREATE INDEX "api_keys_public_id_idx" ON "api_keys"("public_id");CREATE INDEX "api_keys_organization_id_status_idx" ON "api_keys"("organization_id","status");CREATE INDEX "api_keys_service_account_id_idx" ON "api_keys"("service_account_id");CREATE INDEX "service_account_roles_role_id_idx" ON "service_account_roles"("role_id");
ALTER TABLE "service_accounts" ADD CONSTRAINT "service_accounts_organization_id_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "service_accounts" ADD CONSTRAINT "service_accounts_created_by_user_id_fkey" FOREIGN KEY("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "api_keys" ADD CONSTRAINT "api_keys_service_account_id_fkey" FOREIGN KEY("service_account_id") REFERENCES "service_accounts"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "api_keys" ADD CONSTRAINT "api_keys_created_by_user_id_fkey" FOREIGN KEY("created_by_user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "api_keys" ADD CONSTRAINT "api_keys_revoked_by_user_id_fkey" FOREIGN KEY("revoked_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "api_keys" ADD CONSTRAINT "api_keys_replacement_key_id_fkey" FOREIGN KEY("replacement_key_id") REFERENCES "api_keys"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "service_account_roles" ADD CONSTRAINT "service_account_roles_service_account_id_fkey" FOREIGN KEY("service_account_id") REFERENCES "service_accounts"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "service_account_roles" ADD CONSTRAINT "service_account_roles_role_id_fkey" FOREIGN KEY("role_id") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE;
INSERT INTO permissions(id,key,description) VALUES(gen_random_uuid(),'service_accounts.read','View service accounts'),(gen_random_uuid(),'service_accounts.create','Create service accounts'),(gen_random_uuid(),'service_accounts.update','Update service accounts'),(gen_random_uuid(),'service_accounts.delete','Archive service accounts'),(gen_random_uuid(),'service_accounts.roles.manage','Manage service account roles'),(gen_random_uuid(),'api_keys.read','View API key metadata'),(gen_random_uuid(),'api_keys.create','Create API keys'),(gen_random_uuid(),'api_keys.rotate','Rotate API keys'),(gen_random_uuid(),'api_keys.revoke','Revoke API keys') ON CONFLICT(key) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name IN('Owner','Admin') OR (r.name='Manager' AND p.key IN('service_accounts.read','api_keys.read')) ON CONFLICT DO NOTHING;
